SELECT location, CASE WHEN budget >= 3992000 THEN 'high' WHEN budget >= 995000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS cnt, MAX(budget) AS max_budget, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(location))) AS location_values FROM departments WHERE location = 'London' AND location <> 'Singapore' GROUP BY location, CASE WHEN budget >= 3992000 THEN 'high' WHEN budget >= 995000 THEN 'mid' ELSE 'low' END HAVING cnt < 2;
